25	func (r *scriptedRunner) Run(_ context.Context, tc toolCmd, progressFn func(string)) ([]byte, error) {
26		r.mu.Lock()
27		r.calls = append(r.calls, tc)
28		lines := r.progress
29		r.mu.Unlock()
30	
